package com.wiseway.service;
import com.wiseway.api.ApiDtos.*; import com.wiseway.domain.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class RecommendationService {
 private final LocationService locations; private final RoutingProvider routing; private final FareCalculationService fares;
 public RecommendationService(LocationService l,RoutingProvider r,FareCalculationService f){locations=l;routing=r;fares=f;}
 public CompareResponse compare(CompareRequest r,Set<String> excluded){var from=locations.resolve(r.origin());var to=locations.resolve(r.destination());if(from.isEmpty()||to.isEmpty())return empty("UNKNOWN_LOCATION","Select a WiseWay location suggestion; the location could not be resolved.");var route=routing.route(from.get(),to.get());if(route.isEmpty())return empty("NO_ROUTE","No road route was returned by the configured routing provider. No distance-based fares were fabricated.");var source=route.get().source();var modes=source.equals("WISEWAY_CURATED_ROUTE")?Set.of("BUS","METRO"):Set.<String>of();var options=new ArrayList<TransportOption>();for(var mode:List.of(TransportMode.BUS,TransportMode.METRO,TransportMode.TRAIN,TransportMode.AUTO,TransportMode.CAB)){var fare=fares.calculate(mode,(int)Math.round(route.get().distanceMetres()));if(fare.amount()!=null&&(mode==TransportMode.AUTO||mode==TransportMode.CAB||modes.contains(mode.name())))options.add(new TransportOption(mode.name().toLowerCase()+"-route",mode,Math.max(1,(int)Math.round(route.get().durationSeconds()/60))+(mode==TransportMode.BUS?8:0),fare.amount(),"INR",mode==TransportMode.BUS?1:0,mode==TransportMode.CAB?1:4,"Route-specific estimate for "+from.get().name()+" → "+to.get().name()+"."));}var c=r.constraints();var result=RecommendationEngine.recommend(options,r.preference()==null?PreferenceProfile.BALANCED:r.preference(),new RecommendationEngine.Constraints(c==null?null:c.maxFare(),r.departureAt(),c==null?null:c.arriveBy()),excluded);return new CompareResponse("ROUTE_"+source,"Distance and duration from "+source+". Fares are formula-based estimates; transit availability is not verified unless supplied by a transit dataset.",result.feasible().stream().map(x->toOption(x,route.get(),modes)).toList(),result.infeasible().stream().map(x->new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),null,List.of(),x.reasons(),modes.contains(x.option().mode().name())?"AVAILABLE":"ESTIMATED_ONLY","CALCULATED_ESTIMATE",source)).toList(),result.noFit(),result.message());}
 public PlanBResponse planB(PlanBRequest r){var c=compare(new CompareRequest(r.origin(),r.destination(),r.departureAt(),r.preference(),r.constraints()),new HashSet<>(Optional.ofNullable(r.excludeOptionIds()).orElse(List.of())));return new PlanBResponse(r.scenario(),c.dataQuality(),"Simulated Plan B; not a live disruption alert.",c.feasibleOptions().isEmpty()?null:c.feasibleOptions().get(0),c.feasibleOptions().size()>1?c.feasibleOptions().subList(1,c.feasibleOptions().size()):List.of(),c.noFeasibleOption(),c.message());}
 private OptionResponse toOption(RecommendationEngine.RankedOption x,RoutingProvider.Route route,Set<String> verified){return new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),x.score(),x.reasons(),List.of(),verified.contains(x.option().mode().name())?"AVAILABLE":"ESTIMATED_ONLY","CALCULATED_ESTIMATE",route.source()+" · "+Math.round(route.distanceMetres())+"m road route");}
 private CompareResponse empty(String q,String m){return new CompareResponse(q,m,List.of(),List.of(),true,m);}
}
